   if(number===7){const rows=[];for(const N of[1,3,4,5,7])rows.push(await makePlan(a,N));for(const p of rows){assert.ok(p.sessions.every(v=>v.exercises.length===p.ejercicios_por_sesion));assert.deepEqual(flat(p).slice(0,14),flat(rows.at(-1)).slice(0,14));}await r.json('size-matrix',rows);observed='N1/3/4/5/7: todas sesionesincluidaultimaexactas, flujo comun aplanado identico.';}

   if(number===8){for(const e of flat(plan)){const pos=s.positions.find(p=>p.id===e.positionId);assert.equal(e.positionComplete,e.techniqueId===pos.tecnicas.at(-1).id);assert.ok(e.pass>=1);}const groups=new Map();for(const e of flat(plan)){const key=e.prioridad+':'+e.pass;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e.techniqueId);}const lastKey=[...groups.keys()].at(-1);for(const[key,values]of groups){const expected=s.positions.filter(p=>p.prioridad===Number(key.split(':')[0])).flatMap(p=>p.tecnicas.map(t=>t.id));assert.deepEqual(values,key===lastKey?expected.slice(0,values.length):expected);}let remaining=0,activePriority;const occurrence=new Map();for(const e of flat(plan)){if(remaining===0){activePriority=e.prioridad;occurrence.set(activePriority,(occurrence.get(activePriority)||0)+1);remaining=s.positions.filter(p=>p.prioridad===activePriority).reduce((n,p)=>n+p.tecnicas.length,0);}assert.equal(e.prioridad,activePriority);assert.equal(e.pass,occurrence.get(activePriority));remaining--;}assert.equal(plan.sessions[0].exercises.at(-1).positionComplete,false);await r.json('pass-occurrence-oracle',Object.fromEntries(occurrence));observed='F2 primera sesion termina B parcial; cierres exactos y bloques completos en arrays. Contador independiente por prioridad empieza1 y aumenta solo al consumir todo el bloque; cada pass coincide y continua entre sesiones.';}

