   if(number===10){const rows=[];for(const positions of[[],[{id:crypto.randomUUID(),posicion:'empty',prioridad:1,tecnicas:[]}]]){const u=await academy.register('empty');await saveRepertoire(u,{...initialVersion(),positions});const c=competition(u.profile.mail);delete c.planId;const catalog=await academy.call('catalog',undefined,academy.trainer.token);await academy.call('commands/competition',{competition:c,expected:catalog.version,operationId:crypto.randomUUID()},academy.trainer.token);const snap=await snapshot(u);assert.equal(snap.plans.length,0);assert.equal(snap.pendingPlanIds.length,1);let reasonShown=false;const view=await show(browser,u,null,r);try{await expect(view.page.locator('.sync-success')).toHaveCount(0);await expect(view.page.locator('.plan-card')).toHaveCount(0);const body=await view.page.locator('body').innerText();await r.json('empty-user-'+rows.length,{snapshot:snap,body});await r.capture(view.page,'empty-user-'+rows.length);reasonShown=/no (?:hay|quedan|tienes).*t[e\u00e9]cnicas entrenables|cat[a\u00e1]logo.*vac[i\u00ed]o/i.test(body);}finally{await view.context.close();}rows.push({snapshot:snap,reasonShown});}await r.json('empty-catalogues',rows);r.result.severity='MEDIA';r.result.incidentTitle='Catalogo vacio asignado sin explicacion funcional';assert.ok(rows.every(x=>x.reasonShown),'En catalogo vacio y posiciones vacias, la UI no informa que faltan tecnicas entrenables: solo indica planes pendientes y solicita una asignacion que ya existe.');observed='Catalogos vacios y posiciones vacias: no planes inventados, advertencia explicita y sincronizacion incompleta verificadas en PWA.';r.finish('APROBADO',observed,'Firestore sintetico, no Google remoto.');complete=true;}

   if(number===11){const c=competition(a.profile.mail),stamp='2026-10-01T00:00:00Z';assert.deepEqual(generatePlan(c,a.profile.mail,s,notes(s),stamp),generatePlan(c,a.profile.mail,s,notes(s),stamp));const before=await snapshot(a);for(let i=0;i<3;i++)await snapshot(a);assert.deepEqual(await snapshot(a),before);observed='Relojfijo determinista; treslecturasrealesWorker conservan instantaneas/generatedAt/versiones.';}

   if(number===12||number===13){const variants=number===12?[[5,180,10,20,1930]]:[[3,155,1,1,935],[1,1,1,3600,3]];const rows=[];for(const[N,T,C,D,total]of variants){const c=competition(a.profile.mail,N);Object.assign(c,{tiempo_por_tecnica_segundos:T,descanso_entre_ciclos_segundos:C,descanso_entre_tecnicas_segundos:D});const config=tabata(c);assert.equal(config.duration,total);assert.equal(config.cycles,2);assert.equal(config.sets,N);const actual=await makePlan(a,N,undefined,undefined,{tiempo_por_tecnica_segundos:T,descanso_entre_ciclos_segundos:C,descanso_entre_tecnicas_segundos:D});plan=actual;const view=await show(browser,a,actual,r);try{const formatted=Math.floor(total/60)+':'+String(total%60).padStart(2,'0');await expect(view.page.locator('.plan-card .timer')).toContainText('Total '+formatted);await expect(view.page.locator('.plan-card .timer')).toContainText('2 ciclos');await expect(view.page.locator('.plan-card .timer')).toContainText(N+' sets');const download=view.page.waitForEvent('download');await view.page.getByRole('button',{name:'Exportar PDF',exact:true}).click();const file=await download,path=r.dir+'/tabata-'+N+'-'+T+'.pdf';await file.saveAs(path);r.result.evidence.push(path);const pdfText=execFileSync('python',['-c',"import sys;sys.path.insert(0,'.qa/python-deps');from pypdf import PdfReader;doc=PdfReader(sys.argv[1]);print('\\n'.join(page.extract_text() or '' for page in doc.pages))",path],{encoding:'utf8',env:{...process.env,PYTHONIOENCODING:'utf-8'}});assert.ok(pdfText.includes(formatted));assert.ok(pdfText.includes('Sin descanso'));await r.json('pdf-tabata-'+N+'-'+T,{text:pdfText,expectedSeconds:total});}finally{await view.context.close();}rows.push({configuration:config,plan:actual});}await r.json('tabata',rows);observed='Duraciones exactas '+variants.map(v=>v[4]).join('/')+' segundos contrastadas en dominio, plan nativo Worker, resumen PWA y PDF descargado/extraido. Dos ciclos, N sets y ausencia de descanso final comprobados.';r.finish('APROBADO',observed,'PDF y persistencia sintetica reales locales; no Google remoto.');complete=true;}

   if(number===14){const legacy=structuredClone(plan);legacy.descanso_entre_ciclos_segundos=0;legacy.descanso_entre_tecnicas_segundos=0;assert.equal(tabata(legacy).duration,2*180*4);const t=structuredClone(s);t.positions[0].tecnicas[0].descripcion_del_alumno='new';t.descriptionUpdates={[t.positions[0].tecnicas[0].id]:'v1'};const updated=updateFuturePlanText(legacy,t,notes(s),today);assert.equal(updated.descanso_entre_ciclos_segundos,0);assert.equal(updated.descanso_entre_tecnicas_segundos,0);await academy.seedPlan(legacy);await saveRepertoire(a,t);const persisted=(await get(a.profile.mail,'plans/'+plan.planId)).data;assert.equal(persisted.descanso_entre_ciclos_segundos,0);assert.equal(persisted.descanso_entre_tecnicas_segundos,0);await r.json('legacy-zero',{before:legacy,after:persisted});observed='Legado C0/D0 publicado en Firestore sintetico, abierto en PWA, fuente actualizada por Worker y configuracion cero conservada.';}

