caseTest('COM 10',{environment:'Suplemento Chromium PWA/Worker local + Firestore sintetico',users:['T entrenador participante','T2 entrenador QA'],adaptation:'Complementa asignacion real DEV ya ejecutada; identidades locales sinteticas independientes.'},async({browser},r)=>{r.includePrevious();const originalTrainer=academy.trainer;try{const own=originalTrainer,sourceData=source(),target=sourceData.positions[0].tecnicas[0].id;await saveRepertoire(own,sourceData);const plan=await makePlan(own,4),second=await academy.register('second-trainer'),profile=await get(second.profile.mail,'profile');await academy.call('commands/role',{mail:second.profile.mail,perfil:'entrenador',expected:profile.version,operationId:crypto.randomUUID()},own.token);const secondTrainer=await academy.call('auth/login',{mail:second.profile.mail,password:academy.password});await uiDescription(browser,own,target,'trainer own description',r);academy.trainer=secondTrainer;await uiComment(browser,own,target,'other trainer comment',r);const after=(await get(own.profile.mail,'plans/'+plan.planId)).data;assert.deepEqual(protectedSessions(after),protectedSessions(plan));assert.deepEqual(signature(after),signature(plan));for(const e of flat({...after,sessions:after.sessions.filter(x=>x.date>today)}).filter(e=>e.techniqueId===target)){assert.equal(e.descripcion_del_alumno,'trainer own description');assert.equal(e.comment,'other trainer comment');}const view=await show(browser,own,after,r);try{await inspectPlan(view.page,after,r,'trainer-competing-own-plan');assert.equal(await view.page.locator('.plan-card input,.plan-card textarea,.plan-card [contenteditable=true]').count(),0);}finally{await view.context.close();}await r.json('trainer-own-plan',{before:plan,after});r.finish('APROBADO','Asignacion entrenador real DEV conservada como evidencia previa. Suplemento local: entrenador competidor edita propio catalogo, segundo entrenador comenta su ficha, futuras apariciones reciben ambos textos y pasado permanece literal; propio plan solo lectura/PDF.','Asignacion real y sincronizacion/textos locales diferenciados; no se afirma equivalente Google para el suplemento.');}finally{academy.trainer=originalTrainer;}});
